create table public.work_type_catalog(id uuid primary key default gen_random_uuid(),name text not null unique,activity public.production_activity not null,default_rate_ars_ha numeric(16,2)not null default 0 check(default_rate_ars_ha>=0),active boolean not null default true,description text,created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.work_type_catalog enable row level security;create policy work_catalog_read on public.work_type_catalog for select to authenticated using(true);create policy work_catalog_manage on public.work_type_catalog for all to authenticated using(public.is_super_admin())with check(public.is_super_admin());
alter table public.field_operations add column work_type_id uuid references public.work_type_catalog(id)on delete set null;alter table public.field_operations add column rate_ars_ha numeric(16,2)not null default 0 check(rate_ars_ha>=0);alter table public.field_operations add column planned_cost_ars numeric(18,2)not null default 0 check(planned_cost_ars>=0);alter table public.field_operations add column priority text not null default 'media'check(priority in('baja','media','alta'));alter table public.field_operations add column responsible text;
drop function if exists public.create_multi_lot_work_order(uuid,date,public.production_activity,text,text,text,public.operation_status,text,jsonb);
create function public.create_multi_lot_work_order(p_farm_id uuid,p_date date,p_activity public.production_activity,p_name text,p_operation_type text,p_contractor text,p_status public.operation_status,p_notes text,p_lots jsonb,p_work_type_id uuid default null,p_rate_ars_ha numeric default 0,p_priority text default 'media',p_responsible text default null)
returns uuid language plpgsql security definer set search_path=''as $$declare v_campaign uuid;v_operation uuid;v_item jsonb;v_lot public.lots;v_total numeric;v_hectares numeric;v_cycle uuid;v_type public.work_type_catalog;begin if not public.can_manage_farm(p_farm_id)then raise exception 'Sin permiso para administrar el campo'using errcode='42501';end if;select id into v_campaign from public.campaigns where farm_id=p_farm_id and p_date between starts_on and ends_on order by starts_on desc limit 1;if v_campaign is null then raise exception 'No existe una campaña para la fecha indicada';end if;select sum((x->>'hectares')::numeric)into v_total from jsonb_array_elements(p_lots)x;if coalesce(v_total,0)<=0 then raise exception 'Debe seleccionar al menos un lote';end if;if p_work_type_id is not null then select * into v_type from public.work_type_catalog where id=p_work_type_id and active;if v_type.id is null then raise exception 'La labor configurada no existe';end if;end if;insert into public.field_operations(farm_id,campaign_id,activity,operation_date,name,operation_type,worked_hectares,contractor,status,notes,created_by,work_type_id,rate_ars_ha,planned_cost_ars,priority,responsible)values(p_farm_id,v_campaign,coalesce(v_type.activity,p_activity),p_date,trim(p_name),coalesce(v_type.name,trim(p_operation_type)),v_total,nullif(trim(p_contractor),''),p_status,nullif(trim(p_notes),''),auth.uid(),p_work_type_id,p_rate_ars_ha,round(v_total*p_rate_ars_ha,2),p_priority,nullif(trim(p_responsible),''))returning id into v_operation;for v_item in select * from jsonb_array_elements(p_lots)loop select * into v_lot from public.lots where id=(v_item->>'lot_id')::uuid and farm_id=p_farm_id and active;v_hectares:=(v_item->>'hectares')::numeric;if v_lot.id is null then raise exception 'Uno de los lotes no pertenece al campo';end if;if v_hectares<=0 or v_hectares>v_lot.hectares then raise exception 'Superficie inválida para %',v_lot.name;end if;select id into v_cycle from public.agricultural_cycles where campaign_id=v_campaign and lot_id=v_lot.id order by created_at desc limit 1;insert into public.field_operation_lots(operation_id,lot_id,agricultural_cycle_id,worked_hectares,cost_percentage)values(v_operation,v_lot.id,v_cycle,v_hectares,round(v_hectares/v_total*100,4));end loop;return v_operation;end;$$;
revoke all on function public.create_multi_lot_work_order(uuid,date,public.production_activity,text,text,text,public.operation_status,text,jsonb,uuid,numeric,text,text)from public;grant execute on function public.create_multi_lot_work_order(uuid,date,public.production_activity,text,text,text,public.operation_status,text,jsonb,uuid,numeric,text,text)to authenticated;
create view public.work_order_analysis with(security_invoker=true)as select o.id,o.farm_id,f.name farm_name,o.operation_date,o.name,o.operation_type,o.activity,o.status,o.priority,o.responsible,o.contractor,o.worked_hectares,o.rate_ars_ha,o.planned_cost_ars,coalesce(sum(a.allocated_amount*case when e.currency='USD'then coalesce((select er.ars_per_usd from public.exchange_rates er where er.rate_date<=e.expense_date order by er.rate_date desc limit 1),1)else 1 end),0)::numeric(18,2)actual_cost_ars,(coalesce(sum(a.allocated_amount*case when e.currency='USD'then coalesce((select er.ars_per_usd from public.exchange_rates er where er.rate_date<=e.expense_date order by er.rate_date desc limit 1),1)else 1 end),0)-o.planned_cost_ars)::numeric(18,2)cost_variance_ars,case when o.status='planificada'and o.operation_date<current_date then 'vencida'when o.status='planificada'and o.operation_date<=current_date+7 then 'proxima'when o.status='realizada'then 'cumplida'else'en_fecha'end schedule_signal from public.field_operations o join public.farms f on f.id=o.farm_id left join public.expense_allocations a on a.operation_id=o.id left join public.expenses e on e.id=a.expense_id and e.status<>'anulado'group by o.id,o.farm_id,f.name,o.operation_date,o.name,o.operation_type,o.activity,o.status,o.priority,o.responsible,o.contractor,o.worked_hectares,o.rate_ars_ha,o.planned_cost_ars;grant select on public.work_order_analysis to authenticated;
